historical_sql:
SELECT School, EILName
FROM schools
WHERE CDSCode = '01612590136051';

generalized_v1_sql:
SELECT School, EILName
FROM schools
WHERE CDSCode = '01612590136051';

SELECT ROUND(
    100.0 * COUNT(DISTINCT fd.uuid) / (SELECT COUNT(*) FROM cards),
    2
) AS percentage
FROM foreign_data AS fd
WHERE fd.language = 'Chinese Simplified';

historical_sql:
SELECT DISTINCT text
FROM cards
WHERE name = 'Benalish Knight';

generalized_v1_sql:
SELECT DISTINCT text
FROM cards
WHERE name = 'Benalish Knight';

historical_sql:
SELECT 100.0 * SUM(CASE WHEN cardKingdomId IS NOT NULL AND cardKingdomId <> '' AND cardKingdomFoilId IS NOT NULL AND cardKingdomFoilId <> '' THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM cards
WHERE setCode = 'CSP';

SELECT COUNT(DISTINCT name) AS cards
FROM cards
WHERE ',' || COALESCE(promoTypes, '') || ',' LIKE '%,release,%';

generalized_v1_sql:
SELECT COUNT(DISTINCT name) AS number_of_cards
FROM cards
WHERE ',' || promoTypes || ',' LIKE '%,release,%';

SELECT ROUND(
    100.0 * SUM(CASE WHEN Tags LIKE '%<r>%' THEN 1 ELSE 0 END) / COUNT(*),
    2
)
FROM posts
WHERE OwnerUserId = -1;

historical_sql:
SELECT ROUND(
    100.0 * COUNT(*) FILTER (
        WHERE NOT EXISTS (
            SELECT 1
            FROM "member" m
            WHERE m.link_to_major = major.major_id
        )
    ) / NULLIF(COUNT(*), 0),
    2
) AS percentage
FROM major;

generalized_v1_sql:
SELECT ROUND(
    100.0 * SUM(
        CASE WHEN NOT EXISTS (
            SELECT 1
            FROM "member" AS m
            WHERE m.link_to_major = major.major_id
        ) THEN 1 ELSE 0 END
    ) / COUNT(*),
    2
) AS percentage_unrepresented_majors
FROM major;

historical_sql:
SELECT ROUND(
    100.0 * SUM(CASE WHEN CAST(strftime('%Y', Birthday) AS INTEGER) >= 1960 THEN 1 ELSE 0 END) / COUNT(*),
    1
) AS percentage
FROM Patient
WHERE LOWER(Diagnosis) LIKE '%psoriatic arthritis%';

SELECT ROUND(
    100.0 * SUM(CASE WHEN Diagnosis LIKE 'SLE%' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS percentage
FROM Examination
WHERE Thrombosis > 0;

SELECT COUNT(DISTINCT ID) AS patient_count
FROM Patient
WHERE Diagnosis LIKE '%psoriatic arthritis%';

generalized_v1_sql:
SELECT COUNT(DISTINCT ID)
FROM Patient
WHERE lower(Diagnosis) LIKE '%psoriatic arthritis%';

historical_sql:
SELECT ROUND(
    100.0 * SUM(
        CASE WHEN NOT EXISTS (
            SELECT 1
            FROM atom a
            WHERE a.molecule_id = m.molecule_id
              AND a.element = 'F'
        ) THEN 1 ELSE 0 END
    ) / COUNT(*),
    2
) AS percentage
FROM molecule m
WHERE m.label = '+';

generalized_v1_sql:
SELECT ROUND(
    100.0 * SUM(CASE WHEN LOWER(element) = 'cl' THEN 1 ELSE 0 END) / COUNT(*),
    4
)
FROM atom
WHERE molecule_id IN (
    SELECT molecule_id
    FROM bond
    WHERE bond_type = '-'
);

SELECT ROUND(
    1.0 * (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR397') /
    (SELECT COUNT(*) FROM atom WHERE molecule_id = 'TR397'),
    2
) AS average_bonds_per_atom;
